<?php require_once "config/database.php";require_once "includes/functions.php";$pageTitle="Products";$q=trim($_GET["q"]??"");if($q){$s=$pdo->prepare("SELECT * FROM products WHERE name LIKE ? OR category LIKE ? ORDER BY id DESC");$s->execute(["%$q%","%$q%"]);$products=$s->fetchAll();}else{$products=$pdo->query("SELECT * FROM products ORDER BY id DESC")->fetchAll();}require "includes/header.php";?>
<section class="section"><div class="container"><div class="eyebrow">Rasit Collection</div><h1>All Watches</h1><form class="actions" method="get"><input class="input" name="q" value="<?=e($q)?>" placeholder="Search watches..." style="flex:1"><button class="btn">Search</button></form><br><div class="grid"><?php if(!$products):?><div class="empty" style="grid-column:1/-1">No watches found.</div><?php endif;?><?php foreach($products as $p):?><article class="card"><img src="<?=e($p["image"])?>" alt=""><div class="body"><span class="tag"><?=e($p["category"])?></span><h3><?=e($p["name"])?></h3><p style="color:#aaa"><?=e($p["description"])?></p><div class="price">₹<?=number_format((float)$p["price"],2)?></div><div class="actions"><a class="btn" href="product.php?id=<?=$p["id"]?>">Details</a><form action="actions/add_to_cart.php" method="post"><input type="hidden" name="product_id" value="<?=$p["id"]?>"><button class="btn secondary">Add</button></form><a class="btn secondary" href="actions/wishlist.php?id=<?=$p["id"]?>">♡</a></div></div></article><?php endforeach;?></div></div></section><?php require "includes/footer.php";?>